// Real syscall function for MIPS
static long real_syscall6(long syscall_num, long arg1, long arg2, long arg3,
                     long arg4, long arg5, long arg6) {
    long result;

    /*
     * Hacky MIPS syscall approach:
     * - Syscall number goes in $v0 (register 2)
