#!/usr/bin/env node
'use strict';

const fs = require('fs');
const os = require('os');
const path = require('path');

// The guest program uses relative paths (doom.wad, save files), so keep them
// anchored next to this script regardless of where node was launched.
process.chdir(__dirname);

const ELF_FILE = path.join(__dirname, 'doomgeneric_mips');
const MEM_SIZE = 0x50000000;
const STACK_TOP = 0x4f000000;
const ENTRY = 0x400110;

function loadElf(file) {
  const buf = fs.readFileSync(file);
  if (buf.length < 52 || buf.readUInt32BE(0) !== 0x7f454c46) {
    throw new Error('Not an ELF file');
  }
  if (buf[4] !== 1 || buf[5] !== 1) {
    throw new Error('Only ELF32 little-endian is supported');
  }
  const entry = buf.readUInt32LE(24);
  const phoff = buf.readUInt32LE(28);
  const phentsize = buf.readUInt16LE(42);
  const phnum = buf.readUInt16LE(44);
  const mem = new Uint8Array(MEM_SIZE);
  for (let i = 0; i < phnum; i++) {
    const off = phoff + i * phentsize;
    const type = buf.readUInt32LE(off);
    if (type !== 1) continue; // PT_LOAD
    const p_offset = buf.readUInt32LE(off + 4);
    const p_vaddr = buf.readUInt32LE(off + 8);
    const p_filesz = buf.readUInt32LE(off + 16);
    const p_memsz = buf.readUInt32LE(off + 20);
    if (p_vaddr + p_memsz > MEM_SIZE) {
      throw new Error('ELF segment does not fit in memory');
    }
    if (p_filesz) buf.copy(mem, p_vaddr, p_offset, p_offset + p_filesz);
  }
  return { entry, mem };
}

function errnoFor(e) {
  const codes = os.constants.errno;
  if (e && e.code && Object.prototype.hasOwnProperty.call(codes, e.code)) {
    return codes[e.code];
  }
  return codes.EIO || 5;
}

function runVM() {
  const elf = loadElf(ELF_FILE);
  const mem = elf.mem;
  const dv = new DataView(mem.buffer);
  const reg = new Int32Array(32);
  let hi = 0, lo = 0;
  let pc = (elf.entry >>> 0);

  // MIPS hard-float register file (raw 32-bit halves).
  const fpr = new Uint32Array(32);
  const fbuf = new ArrayBuffer(8);
  const fdv = new DataView(fbuf);
  function getS(i) { fdv.setUint32(0, fpr[i], true); return fdv.getFloat32(0, true); }
  function setS(i, v) { fdv.setFloat32(0, v, true); fpr[i] = fdv.getUint32(0, true); }
  function getD(i) {
    i &= ~1;
    fdv.setUint32(0, fpr[i], true);
    fdv.setUint32(4, fpr[i + 1], true);
    return fdv.getFloat64(0, true);
  }
  function setD(i, v) {
    i &= ~1;
    fdv.setFloat64(0, v, true);
    fpr[i] = fdv.getUint32(0, true);
