#!/usr/bin/env node
'use strict';

const fs = require('fs');
const os = require('os');
const path = require('path');

// The guest program uses relative paths (doom.wad, save files), so keep them
// anchored next to this script regardless of where node was launched.
process.chdir(__dirname);

const ELF_FILE = path.join(__dirname, 'doomgeneric_mips');
const MEM_SIZE = 0x50000000;
const STACK_TOP = 0x4f000000;

function loadElf(file) {
  const buf = fs.readFileSync(file);
  if (buf.length < 52 || buf.readUInt32BE(0) !== 0x7f454c46) {
    throw new Error('Not an ELF file');
  }
  if (buf[4] !== 1 || buf[5] !== 1) {
    throw new Error('Only ELF32 little-endian is supported');
  }
  const entry = buf.readUInt32LE(24);
  const phoff = buf.readUInt32LE(28);
  const phentsize = buf.readUInt16LE(42);
  const phnum = buf.readUInt16LE(44);
  const mem = new Uint8Array(MEM_SIZE);
  for (let i = 0; i < phnum; i++) {
    const off = phoff + i * phentsize;
    const type = buf.readUInt32LE(off);
    if (type !== 1) continue; // PT_LOAD
    const p_offset = buf.readUInt32LE(off + 4);
    const p_vaddr = buf.readUInt32LE(off + 8);
    const p_filesz = buf.readUInt32LE(off + 16);
    const p_memsz = buf.readUInt32LE(off + 20);
    if (p_vaddr + p_memsz > MEM_SIZE) {
      throw new Error('ELF segment does not fit in memory');
    }
    if (p_filesz) buf.copy(mem, p_vaddr, p_offset, p_offset + p_filesz);
  }
  return { entry, mem };
}

function errnoFor(e) {
  const codes = os.constants.errno;
  if (e && e.code && Object.prototype.hasOwnProperty.call(codes, e.code)) {
    return codes[e.code];
  }
  return codes.EIO || 5;
}

function runVM() {
  const elf = loadElf(ELF_FILE);
  const mem = elf.mem;
  const dv = new DataView(mem.buffer);
  const reg = new Int32Array(32);
  let hi = 0, lo = 0;
  let pc = (elf.entry >>> 0);

  // MIPS hard-float register file (raw 32-bit halves).
  const fpr = new Uint32Array(32);
  const fbuf = new ArrayBuffer(8);
  const fdv = new DataView(fbuf);
  function getS(i) { fdv.setUint32(0, fpr[i], true); return fdv.getFloat32(0, true); }
  function setS(i, v) { fdv.setFloat32(0, v, true); fpr[i] = fdv.getUint32(0, true); }
  function getD(i) {
    i &= ~1;
    fdv.setUint32(0, fpr[i], true);
    fdv.setUint32(4, fpr[i + 1], true);
    return fdv.getFloat64(0, true);
  }
  function setD(i, v) {
    i &= ~1;
    fdv.setFloat64(0, v, true);
    fpr[i] = fdv.getUint32(0, true);
    fpr[i + 1] = fdv.getUint32(4, true);
  }
  let fcc0 = false;

  // syscall state
  const fdState = new Map(); // fd -> {pos, flags, append}
  function guestString(addr) {
    let end = addr;
    while (end < mem.length && mem[end] !== 0) end++;
    return Buffer.from(mem.buffer, addr, end - addr).toString('utf8');
  }
  function doSyscall() {
    const num = reg[2] >>> 0;
    const a0 = reg[4] >>> 0;
    const a1 = reg[5] >>> 0;
    const a2 = reg[6] >>> 0;
    let ret = 0;
    try {
      switch (num) {
        case 0: { // read
          const fd = a0 | 0;
          const len = a2 >>> 0;
          let n;
          if (fd === 0) {
            n = fs.readSync(0, mem, a1, len, null);
          } else {
            const st = fdState.get(fd);
            const pos = st ? st.pos : null;
            n = fs.readSync(fd, mem, a1, len, st ? pos : null);
            if (st) st.pos += n;
          }
          ret = n;
          break;
        }
        case 1: { // write
          const fd = a0 | 0;
          const len = a2 >>> 0;
          if (len === 0) { ret = 0; break; }
          if (fd === 1 || fd === 2) {
            ret = fs.writeSync(fd, mem, a1, len, null);
          } else {
            let st = fdState.get(fd);
            if (!st) { st = { pos: null, flags: 0, append: false }; fdState.set(fd, st); }
            let pos = st.append ? fs.fstatSync(fd).size : st.pos;
            ret = fs.writeSync(fd, mem, a1, len, pos);
            if (st.append) st.pos = pos + ret; else st.pos += ret;
          }
          break;
        }
        case 2: { // open
          const name = guestString(a0);
          if (process.env.VM_STATS && /frame\.bmp$/.test(name)) {
            process.stderr.write(`vm.js: frame file opened after ${count} instructions\n`);
          }
          const flags = a1 | 0;
          const mode = (a2 & 0o777) || 0o644;
          const fd = fs.openSync(name, flags, mode);
          fdState.set(fd, { pos: 0, flags, append: (flags & 1024) !== 0 });
          ret = fd;
          break;
        }
        case 3: { // close
          const fd = a0 | 0;
          try { fs.closeSync(fd); } catch (e) { /* already gone */ }
          fdState.delete(fd);
          ret = 0;
          break;
        }
        case 8: { // lseek
          const fd = a0 | 0;
          const off = a1 | 0;
          const whence = a2 | 0;
          let st = fdState.get(fd);
          if (!st) { st = { pos: 0, flags: 0, append: false }; fdState.set(fd, st); }
          let base;
          if (whence === 0) base = 0;
          else if (whence === 1) base = st.pos || 0;
          else if (whence === 2) {
            try { base = fs.fstatSync(fd).size; } catch (e) { base = 0; }
          } else { ret = -22; break; }
          st.pos = base + off;
          ret = st.pos;
          break;
        }
        case 12: // brk (unused by this binary's allocator, but harmless)
          ret = 0x50000000;
          break;
        case 60: // exit
        case 231: // exit_group
          process.exitCode = a0 & 0xff;
          return false;
        case 74: // fsync
          ret = 0;
          break;
        case 82: { // rename
          fs.renameSync(guestString(a0), guestString(a1));
          ret = 0;
          break;
        }
        case 83: { // mkdir
          fs.mkdirSync(guestString(a0), (a1 & 0o777) || 0o755);
          ret = 0;
          break;
        }
        case 87: // unlink
          fs.unlinkSync(guestString(a0));
          ret = 0;
          break;
        case 201: { // time
          const t = Math.floor(Date.now() / 1000);
          if (a0) dv.setInt32(a0, t, true);
          ret = t;
          break;
        }
        default:
          process.stderr.write(`vm.js: unimplemented syscall ${num} (a0=${a0} a1=${a1} a2=${a2})\n`);
          ret = -38; // ENOSYS
          break;
      }
    } catch (e) {
      ret = -errnoFor(e);
    }
    reg[2] = ret | 0;
    return true;
  }

  // Registers: 0 zero, 4-7 a0-a3, 8-9 t0-t1, 29 sp, 31 ra.
  reg[29] = STACK_TOP;
  const INS_LIMIT = process.env.VM_INS_LIMIT ? Number(process.env.VM_INS_LIMIT) : 0;

  let count = 0;
  let branchTarget = -1;
  let running = true;

  function execute(ins, cur) {
    // Returns nothing; updates branchTarget for control transfers.
    const op = ins >>> 26;
    const rs = (ins >>> 21) & 31;
    const rt = (ins >>> 16) & 31;
    const rd = (ins >>> 11) & 31;
    const sa = (ins >>> 6) & 31;
    const funct = ins & 63;

    switch (op) {
      case 0: { // SPECIAL
        switch (funct) {
          case 0: reg[rd] = reg[rt] << sa; break; // sll
          case 2: reg[rd] = reg[rt] >>> sa; break; // srl
          case 3: reg[rd] = reg[rt] >> sa; break; // sra
          case 4: reg[rd] = reg[rt] << (reg[rs] & 31); break; // sllv
          case 6: // srlv / rotr
            if (rs === 1) { const n = sa; reg[rd] = ((reg[rt] >>> n) | (reg[rt] << (32 - n))) >>> 0 | 0; }
            else reg[rd] = reg[rt] >>> (reg[rs] & 31);
            break;
          case 7: reg[rd] = reg[rt] >> (reg[rs] & 31); break; // srav
          case 8: branchTarget = reg[rs] >>> 0; break; // jr
          case 9: { const link = (cur + 8) >>> 0; branchTarget = reg[rs] >>> 0; if (rd) reg[rd] = link | 0; break; } // jalr
          case 10: if (reg[rt] === 0) reg[rd] = reg[rs]; break; // movz
          case 11: if (reg[rt] !== 0) reg[rd] = reg[rs]; break; // movn
          case 12: if (!doSyscall()) running = false; break; // syscall
          case 13: // break
            running = false; break;
          case 15: break; // sync
          case 16: reg[rd] = hi; break; // mfhi
          case 17: hi = reg[rs]; break; // mthi
          case 18: reg[rd] = lo; break; // mflo
          case 19: lo = reg[rs]; break; // mtlo
          case 24: { // mult
            const a = reg[rs] | 0, b = reg[rt] | 0;
            const p = BigInt(a) * BigInt(b);
            lo = Number(p & 0xffffffffn) | 0;
            hi = Number((p >> 32n) & 0xffffffffn) | 0;
            break;
          }
          case 25: { // multu
            const p = BigInt(reg[rs] >>> 0) * BigInt(reg[rt] >>> 0);
            lo = Number(p & 0xffffffffn) | 0;
            hi = Number((p >> 32n) & 0xffffffffn) | 0;
            break;
          }
          case 26: { // div
            const a = reg[rs] | 0, b = reg[rt] | 0;
            if (b === 0) { lo = a >= 0 ? -1 : 1; hi = a | 0; }
            else if (a === -2147483648 && b === -1) { lo = -2147483648; hi = 0; }
            else { lo = (a / b) | 0; hi = (a - lo * b) | 0; }
            break;
          }
          case 27: { // divu
            const a = reg[rs] >>> 0, b = reg[rt] >>> 0;
            if (b === 0) { lo = -1; hi = a | 0; }
            else { lo = Math.floor(a / b) | 0; hi = (a - (lo >>> 0) * b) | 0; }
            break;
          }
          case 32: reg[rd] = (reg[rs] + reg[rt]) | 0; break; // add
          case 33: reg[rd] = (reg[rs] + reg[rt]) | 0; break; // addu
          case 34: reg[rd] = (reg[rs] - reg[rt]) | 0; break; // sub
          case 35: reg[rd] = (reg[rs] - reg[rt]) | 0; break; // subu
          case 36: reg[rd] = reg[rs] & reg[rt]; break;
          case 37: reg[rd] = reg[rs] | reg[rt]; break;
          case 38: reg[rd] = reg[rs] ^ reg[rt]; break;
          case 39: reg[rd] = ~(reg[rs] | reg[rt]); break;
          case 42: reg[rd] = reg[rs] < reg[rt] ? 1 : 0; break; // slt
          case 43: reg[rd] = (reg[rs] >>> 0) < (reg[rt] >>> 0) ? 1 : 0; break; // sltu
          case 52: if (reg[rs] === reg[rt]) throw new Error(`teq trap at 0x${cur.toString(16)}`); break;
          default: throw new Error(`unimplemented SPECIAL funct ${funct} at 0x${cur.toString(16)}`);
        }
        break;
      }
      case 1: { // REGIMM
        const imm = (ins << 16) >> 16;
        const target = (cur + 4 + (imm << 2)) >>> 0;
        switch (rt) {
          case 0: if (reg[rs] < 0) branchTarget = target; break; // bltz
          case 1: if (reg[rs] >= 0) branchTarget = target; break; // bgez
          case 16: { const link = (cur + 8) >>> 0; if (reg[rs] < 0) branchTarget = target; if (rt) reg[31] = link | 0; break; } // bltzal
          case 17: { const link = (cur + 8) >>> 0; if (reg[rs] >= 0) branchTarget = target; reg[31] = link | 0; break; } // bgezal
          default: throw new Error(`unimplemented REGIMM rt ${rt} at 0x${cur.toString(16)}`);
        }
        break;
      }
      case 2: branchTarget = (((cur + 4) & 0xf0000000) | ((ins & 0x03ffffff) << 2)) >>> 0; break; // j
      case 3: { // jal
        const link = (cur + 8) >>> 0;
        branchTarget = (((cur + 4) & 0xf0000000) | ((ins & 0x03ffffff) << 2)) >>> 0;
        reg[31] = link | 0;
        break;
      }
      case 4: if (reg[rs] === reg[rt]) branchTarget = (cur + 4 + ((ins << 16) >> 16) * 4) >>> 0; break; // beq
      case 5: if (reg[rs] !== reg[rt]) branchTarget = (cur + 4 + ((ins << 16) >> 16) * 4) >>> 0; break; // bne
      case 6: if (reg[rs] <= 0) branchTarget = (cur + 4 + ((ins << 16) >> 16) * 4) >>> 0; break; // blez
      case 7: if (reg[rs] > 0) branchTarget = (cur + 4 + ((ins << 16) >> 16) * 4) >>> 0; break; // bgtz
      case 8: reg[rt] = (reg[rs] + ((ins << 16) >> 16)) | 0; break; // addi
      case 9: reg[rt] = (reg[rs] + ((ins << 16) >> 16)) | 0; break; // addiu
      case 10: reg[rt] = reg[rs] < ((ins << 16) >> 16) ? 1 : 0; break; // slti
      case 11: reg[rt] = (reg[rs] >>> 0) < (((ins << 16) >> 16) >>> 0) ? 1 : 0; break; // sltiu
      case 12: reg[rt] = reg[rs] & (ins & 0xffff); break;
      case 13: reg[rt] = reg[rs] | (ins & 0xffff); break;
      case 14: reg[rt] = reg[rs] ^ (ins & 0xffff); break;
      case 15: reg[rt] = (ins & 0xffff) << 16; break; // lui
      case 17: { // COP1
        if (rs === 0) { // mfc1
          if (rt) reg[rt] = fpr[rd] | 0;
        } else if (rs === 2) { // cfc1
          if (rt) reg[rt] = 0; // FCR31
        } else if (rs === 4) { // mtc1
          fpr[rd] = reg[rt] >>> 0;
        } else if (rs === 6) { // ctc1
          // ignore FCR31 writes
        } else if (rs === 3) { // mfhc1
          if (rt) reg[rt] = fpr[rd | 1] | 0;
        } else if (rs === 7) { // mthc1
          fpr[rd | 1] = reg[rt] >>> 0;
        } else if (rs === 8) { // bc1f/bc1t
          const target = (cur + 4 + ((ins << 16) >> 16) * 4) >>> 0;
          const cond = (rt & 1) === 1;
          if (fcc0 === cond) branchTarget = target;
        } else {
          const fmt = rs;
          const ft = rt;
          const fs = rd;
          const fd = sa;
          if (fmt === 16) { // single
            const a = getS(fs), b = getS(ft);
            switch (funct) {
              case 0: setS(fd, a + b); break;
              case 1: setS(fd, a - b); break;
              case 2: setS(fd, a * b); break;
              case 3: setS(fd, a / b); break;
              case 4: setS(fd, Math.sqrt(a)); break;
              case 5: setS(fd, Math.abs(a)); break;
              case 6: setS(fd, a); break;
              case 7: setS(fd, -a); break;
              case 13: fpr[fd] = Math.trunc(a) | 0; break; // trunc.w.s
              case 12: fpr[fd] = Math.round(a) | 0; break; // round.w.s
              case 14: fpr[fd] = Math.ceil(a) | 0; break;
              case 15: fpr[fd] = Math.floor(a) | 0; break;
              case 17: if (fcc0) setS(fd, a); break; // movt.s
              case 32: setS(fd, a); break; // cvt.s.s
              case 33: setD(fd, a); break; // cvt.d.s
              case 36: fpr[fd] = Math.trunc(a) | 0; break; // cvt.w.s
              case 48: fcc0 = false; break; // c.f.s
              case 49: fcc0 = Number.isNaN(a) || Number.isNaN(b); break; // c.un
              case 50: fcc0 = a === b; break;
              case 51: fcc0 = Number.isNaN(a) || Number.isNaN(b) || a === b; break;
              case 52: fcc0 = a < b; break;
              case 53: fcc0 = Number.isNaN(a) || Number.isNaN(b) || a < b; break;
              case 54: fcc0 = a <= b; break;
              case 55: fcc0 = Number.isNaN(a) || Number.isNaN(b) || a <= b; break;
              default: throw new Error(`unimplemented COP1.s funct ${funct} at 0x${cur.toString(16)}`);
            }
          } else if (fmt === 17) { // double
            const a = getD(fs), b = getD(ft);
            switch (funct) {
              case 0: setD(fd, a + b); break;
              case 1: setD(fd, a - b); break;
              case 2: setD(fd, a * b); break;
              case 3: setD(fd, a / b); break;
              case 4: setD(fd, Math.sqrt(a)); break;
              case 5: setD(fd, Math.abs(a)); break;
              case 6: setD(fd, a); break;
              case 7: setD(fd, -a); break;
              case 13: fpr[fd] = Math.trunc(a) | 0; break; // trunc.w.d
              case 17: if (fcc0) setD(fd, a); break; // movt.d
              case 32: setS(fd, a); break; // cvt.s.d
              case 33: setD(fd, a); break; // cvt.d.d
              case 36: fpr[fd] = Math.trunc(a) | 0; break; // cvt.w.d
              case 48: fcc0 = false; break;
              case 49: fcc0 = Number.isNaN(a) || Number.isNaN(b); break;
              case 50: fcc0 = a === b; break;
              case 51: fcc0 = Number.isNaN(a) || Number.isNaN(b) || a === b; break;
              case 52: fcc0 = a < b; break;
              case 53: fcc0 = Number.isNaN(a) || Number.isNaN(b) || a < b; break;
              case 54: fcc0 = a <= b; break;
              case 55: fcc0 = Number.isNaN(a) || Number.isNaN(b) || a <= b; break;
              default: throw new Error(`unimplemented COP1.d funct ${funct} at 0x${cur.toString(16)}`);
            }
          } else if (fmt === 20) { // word
            const a = fpr[fs] | 0;
            switch (funct) {
              case 32: setS(fd, a); break; // cvt.s.w
              case 33: setD(fd, a); break; // cvt.d.w
              case 36: fpr[fd] = a | 0; break;
              default: throw new Error(`unimplemented COP1.w funct ${funct} at 0x${cur.toString(16)}`);
            }
          } else {
            throw new Error(`unimplemented COP1 fmt ${fmt} at 0x${cur.toString(16)}`);
          }
        }
        break;
      }
      case 28: { // SPECIAL2
        switch (funct) {
          case 0: { // madd
            const p = BigInt(reg[rs] | 0) * BigInt(reg[rt] | 0) + (BigInt(hi) << 32n) + BigInt(lo >>> 0);
            lo = Number(p & 0xffffffffn) | 0; hi = Number((p >> 32n) & 0xffffffffn) | 0; break;
          }
          case 1: { // maddu
            const p = BigInt(reg[rs] >>> 0) * BigInt(reg[rt] >>> 0) + (BigInt(hi >>> 0) << 32n) + BigInt(lo >>> 0);
            lo = Number(p & 0xffffffffn) | 0; hi = Number((p >> 32n) & 0xffffffffn) | 0; break;
          }
          case 2: reg[rd] = Math.imul(reg[rs], reg[rt]); break; // mul
          case 32: { let v = reg[rs] >>> 0; let n = 0; while (n < 32 && (v & 0x80000000) === 0) { v = (v << 1) >>> 0; n++; } reg[rd] = n; break; } // clz
          case 33: { let v = reg[rs] >>> 0; let n = 0; while (n < 32 && (v & 0x80000000) !== 0) { v = (v << 1) >>> 0; n++; } reg[rd] = n; break; } // clo
          default: throw new Error(`unimplemented SPECIAL2 funct ${funct} at 0x${cur.toString(16)}`);
        }
        break;
      }
      case 31: { // SPECIAL3
        if (funct === 0) { // ext
          const pos = sa, size = rd + 1;
          const mask = (0xffffffff >>> (32 - size));
          reg[rt] = ((reg[rs] >>> pos) & mask) | 0;
        } else if (funct === 4) { // ins
          const pos = sa, size = rd - sa + 1;
          const mask = ((0xffffffff >>> (32 - size)) << pos) >>> 0;
          reg[rt] = ((reg[rt] & ~mask) | ((reg[rs] << pos) & mask)) | 0;
        } else if (funct === 32) { // bshfl
          switch (sa) {
            case 2: reg[rd] = ((reg[rt] & 0x00ff00ff) << 8) | ((reg[rt] >>> 8) & 0x00ff00ff); break; // wsbh
            case 16: reg[rd] = (reg[rt] << 24) >> 24; break; // seb
            case 24: reg[rd] = (reg[rt] << 16) >> 16; break; // seh
            default: throw new Error(`unimplemented BSHFL sa ${sa} at 0x${cur.toString(16)}`);
          }
        } else {
          throw new Error(`unimplemented SPECIAL3 funct ${funct} at 0x${cur.toString(16)}`);
        }
        break;
      }
      case 32: reg[rt] = dv.getInt8(reg[rs] + ((ins << 16) >> 16)); break; // lb
      case 33: reg[rt] = dv.getInt16(reg[rs] + ((ins << 16) >> 16), true); break; // lh
      case 34: { // lwl
        const addr = (reg[rs] + ((ins << 16) >> 16)) >>> 0;
        const n = addr & 3, aligned = (addr & ~3) >>> 0;
        const word = dv.getUint32(aligned, true);
        const mask = n === 3 ? 0 : (0xffffffff >>> (8 * (n + 1)));
        reg[rt] = ((reg[rt] & mask) | (word << (8 * (3 - n)))) | 0;
        break;
      }
      case 35: reg[rt] = dv.getInt32((reg[rs] + ((ins << 16) >> 16)) >>> 0, true); break; // lw
      case 36: reg[rt] = dv.getUint8(reg[rs] + ((ins << 16) >> 16)); break; // lbu
      case 37: reg[rt] = dv.getUint16((reg[rs] + ((ins << 16) >> 16)) >>> 0, true); break; // lhu
      case 38: { // lwr
        const addr = (reg[rs] + ((ins << 16) >> 16)) >>> 0;
        const n = addr & 3, aligned = (addr & ~3) >>> 0;
        const word = dv.getUint32(aligned, true);
        const mask = n === 0 ? 0 : (0xffffffff << (8 * (4 - n)));
        reg[rt] = ((reg[rt] & mask) | (word >>> (8 * n))) | 0;
        break;
      }
      case 39: reg[rt] = dv.getUint32((reg[rs] + ((ins << 16) >> 16)) >>> 0, true); break; // lwu
      case 40: mem[(reg[rs] + ((ins << 16) >> 16)) >>> 0] = reg[rt] & 0xff; break; // sb
      case 41: dv.setInt16((reg[rs] + ((ins << 16) >> 16)) >>> 0, reg[rt], true); break; // sh
      case 42: { // swl
        const addr = (reg[rs] + ((ins << 16) >> 16)) >>> 0;
        const n = addr & 3, aligned = (addr & ~3) >>> 0;
        for (let i = 0; i <= n; i++) mem[aligned + i] = (reg[rt] >>> (8 * (3 - n + i))) & 0xff;
        break;
      }
      case 43: dv.setInt32((reg[rs] + ((ins << 16) >> 16)) >>> 0, reg[rt], true); break; // sw
      case 46: { // swr
        const addr = (reg[rs] + ((ins << 16) >> 16)) >>> 0;
        const n = addr & 3, aligned = (addr & ~3) >>> 0;
        for (let i = n; i <= 3; i++) mem[aligned + i] = (reg[rt] >>> (8 * (i - n))) & 0xff;
        break;
      }
      case 47: break; // cache
      case 48: reg[rt] = dv.getInt32((reg[rs] + ((ins << 16) >> 16)) >>> 0, true); break; // ll
      case 49: fpr[rt] = dv.getUint32((reg[rs] + ((ins << 16) >> 16)) >>> 0, true); break; // lwc1
      case 51: break; // pref
      case 53: { // ldc1
        const addr = (reg[rs] + ((ins << 16) >> 16)) >>> 0;
        fpr[rt] = dv.getUint32(addr, true);
        fpr[rt | 1] = dv.getUint32(addr + 4, true);
        break;
      }
      case 56: reg[rt] = 1; break; // sc (always succeeds)
      case 57: dv.setUint32((reg[rs] + ((ins << 16) >> 16)) >>> 0, fpr[rt], true); break; // swc1
      case 61: { // sdc1
